class Solution {
public:
    int maximumAmount(vector<vector<int>>& coins) {
        int m = coins.size(), n = coins[0].size();
        vector<vector<vector<long long>>> dp(m, vector<vector<long long>>(n, vector<long long>(3, -1e18)));

        for (int k = 0; k < 3; ++k) {
            if (coins[0][0] < 0 && k > 0) dp[0][0][k] = 0;
            else dp[0][0][k] = coins[0][0];
        }

        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                for (int k = 0; k < 3; ++k) {
                    long long val = coins[i][j];
                    if (i > 0) {
                        dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k] + val);
                        if (val < 0 && k > 0) dp[i][j][k] = max(dp[i][j][k], dp[i - 1][j][k - 1]);
                    }
                    if (j > 0) {
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j - 1][k] + val);
                        if (val < 0 && k > 0) dp[i][j][k] = max(dp[i][j][k], dp[i][j - 1][k - 1]);
                    }
                }
            }
        }
        return max({dp[m - 1][n - 1][0], dp[m - 1][n - 1][1], dp[m - 1][n - 1][2]});
    }
};

class Solution {
    public int maximumAmount(int[][] coins) {
        int m = coins.length, n = coins[0].length;
        long[][][] dp = new long[m][n][3];
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                Arrays.fill(dp[i][j], (long)-1e18);
            }
        }

        for (int k = 0; k < 3; ++k) {
            if (coins[0][0] < 0 && k > 0) dp[0][0][k] = 0;
            else dp[0][0][k] = coins[0][0];
        }

        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                for (int k = 0; k < 3; ++k) {
                    long val = coins[i][j];
                    if (i > 0) {
                        dp[i][j][k] = Math.max(dp[i][j][k], dp[i - 1][j][k] + val);
                        if (val < 0 && k > 0) dp[i][j][k] = Math.max(dp[i][j][k], dp[i - 1][j][k - 1]);
                    }
                    if (j > 0) {
                        dp[i][j][k] = Math.max(dp[i][j][k], dp[i][j - 1][k] + val);
                        if (val < 0 && k > 0) dp[i][j][k] = Math.max(dp[i][j][k], dp[i][j - 1][k - 1]);
                    }
                }
            }
        }
        return (int) Math.max(dp[m - 1][n - 1][0], Math.max(dp[m - 1][n - 1][1], dp[m - 1][n - 1][2]));
    }
}

